import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.CDU0sSpB.js";const k=JSON.parse('{"title":"Quick start","description":"Install Hearth locally, start it, and complete the first task.","frontmatter":{"title":"Quick start","description":"Install Hearth locally, start it, and complete the first task.","outline":[2,3]},"headers":[],"relativePath":"en/guide/index.md","filePath":"en/guide/index.md","lastUpdated":1793797632000}'),n={name:"en/guide/index.md"};function r(l,e,o,h,d,p){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick start&quot;">​</a></h1><p class="lead">Hearth is a local-first, single-user application. The server, database, and web control plane all run on your machine and listen only on loopback by default.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Requirement</th></tr></thead><tbody><tr><td>Node.js</td><td>22.13 or newer (the server uses the built-in <code>node:sqlite</code>; verified on 26.11.1)</td></tr><tr><td>npm</td><td>Included with Node.js</td></tr><tr><td>Operating system</td><td>Windows, macOS, or Linux; desktop control currently requires the same-machine Windows helper</td></tr><tr><td>Model</td><td>Any tool-calling OpenAI Chat, OpenAI Responses, Anthropic Messages, or Gemini-compatible service</td></tr></tbody></table><h2 id="install-and-start" tabindex="-1">Install and start <a class="header-anchor" href="#install-and-start" aria-label="Permalink to &quot;Install and start&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/hearthproject/hearth-os.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hearth-os</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>Open <a href="http://127.0.0.1:5173" target="_blank" rel="noreferrer">http://127.0.0.1:5173</a>. Development mode starts two processes:</p><ul><li><code>@hearth/server</code>: Fastify API and scheduler on <code>127.0.0.1:4317</code>.</li><li><code>@hearth/web</code>: Vite dev server, proxying <code>/api</code> to the local service.</li></ul><p>Production-style local run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>Open <a href="http://127.0.0.1:4317" target="_blank" rel="noreferrer">http://127.0.0.1:4317</a>. The server serves the built web assets directly.</p><h2 id="complete-the-first-task" tabindex="-1">Complete the first task <a class="header-anchor" href="#complete-the-first-task" aria-label="Permalink to &quot;Complete the first task&quot;">​</a></h2><ol><li>Open <strong>Settings</strong>, choose a model provider, and fill in Base URL, model, and API key. Click <strong>Test connection</strong>.</li><li>Return to <strong>Chat</strong> and describe the work in one sentence, for example: &quot;Turn this meeting transcript into action minutes with owners and dates.&quot;</li><li>General tasks are dispatched directly. Tasks that need network access or a writable engineering workspace first produce a <strong>task proposal</strong>; the task enters the queue only after you confirm.</li><li>Open <strong>Tasks</strong> to inspect status, executor, tokens, duration, and artifacts. A task waiting for input can be continued from chat.</li><li>External actions appear as approval cards. An approval binds to a parameter fingerprint, executes once, and stores a receipt.</li></ol><h2 id="where-data-lives" tabindex="-1">Where data lives <a class="header-anchor" href="#where-data-lives" aria-label="Permalink to &quot;Where data lives&quot;">​</a></h2><p>The default data directory is <code>.hearth/</code> at the repository root. Override it with <code>HEARTH_DATA_DIR</code>, <code>HEARTH_PORT</code>, or <code>HEARTH_HOST</code>.</p><p>For example, in a Windows terminal:</p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> HEARTH_DATA_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">D:\\HearthData</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">npm </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">start</span></span></code></pre></div><p>On macOS or Linux:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HEARTH_DATA_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/path/to/data</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/hearth-os/en/guide/models.html">Connect a model</a>: four protocols, provider presets, and the Codex executor.</li><li><a href="/hearth-os/en/guide/data.html">Data, backup, and restore</a>: database, artifacts, encrypted backups, and restore boundaries.</li><li><a href="/hearth-os/en/guide/development.html">Development and tests</a>: scripts, tests, documentation, and code layout.</li></ul>`,21)])])}const u=t(n,[["render",r]]);export{k as __pageData,u as default};
